      subscriptionStartAt: json['subscription_start_at'] as String?,
      successUrl: json['success_url'] as String,
      url: json['url'] as String,
    );
  }

  /// O valor, em centavos, que o seu servidor fixou; o comprador o vê e não
  /// pode mudá-lo. Nulo quando é o comprador quem digita o valor.
  final int? amountCents;

  /// Endereço https para onde o comprador volta se desistir; vazio sem ele.
  final String cancelUrl;

  /// O id do pedido no seu sistema, como o seu servidor o enviou; vazio sem
  /// ele. Volta no checkout, no pedido, no pagamento e nos eventos.
  final String clientReferenceId;

  /// O segredo que o navegador do comprador usa para ler, atualizar e pagar a
  /// sessão, sem chave de API. Só esta resposta o traz; entregue-o à página que
  /// monta os campos seguros. Vem vazio na repetição de uma criação
  /// idempotente.
  final String clientSecret;

  /// Quando a sessão e o client_secret deixam de valer.
  final String clientSecretExpiresAt;

  final String createdAt;

  /// O desconto que o checkout aplica sozinho, como o seu servidor o enviou na
  /// criação; vazio sem ele. O comprador o vê no resumo e ele conta desde a
  /// primeira cobrança.
  final String discountId;

  /// Quando o link deixa de abrir sessões; nulo sem prazo.
  final String? expiresAt;

  /// Quantos dias o seu servidor somou ao primeiro período da assinatura
  /// (first_period_extra_days na criação); nulo quando o primeiro período é o
  /// comum. O comprador paga hoje o valor cheio, e a próxima cobrança só
  /// acontece no fim do período mais longo.
  final int? firstPeriodExtraDays;

  /// O ID do link do checkout, o que GET e PATCH /checkouts/{id} recebem.
  final String id;

  /// As linhas do valor fixado, na ordem em que foram enviadas; vazio sem elas.
  final List<CheckoutLine> items;

  /// Como o lojista chama o checkout nas próprias telas; o comprador não vê.
  final String label;

  /// Os pares que o seu servidor enviou; voltam no pedido, no pagamento e nos
  /// eventos da venda (checkout.*, order.*, checkout_payment.* e refund.*).
  final Map<String, Object?> metadata;

  /// Falso quando o seu sistema avisa o comprador das cobranças de renovação e
  /// a Peráta fica quieta.
  final bool notifyCustomerEmail;

  final String priceId;

  final String productId;

  final int quantity;

  /// O renewal_mode da criação: manual, automatic ou buyer_choice; vazio quando
  /// foi omitido. A assinatura que o pagamento começa traz o modo a que isso se
  /// resolveu em Subscription.renewal_mode.
  ///
  /// One of `manual`, `automatic`, `buyer_choice`.
  final String renewalMode;

  /// O ID da sessão de checkout; as rotas de cliente dela são
  /// /checkouts/client/{client_secret}.
  final String sessionId;

  /// O showcase a que pertence: o da chave de API que fez a chamada. Uma chave
  /// só alcança o seu showcase.
  final String showcaseId;

  /// active abre sessões de compra; archived saiu de circulação.
  ///
  /// One of `active`, `archived`.
  final String status;

  /// Lê o estado da sessão depois que o client_secret é consumido: GET
  /// /checkouts/client/status/{status_key}. Só esta resposta o traz.
  final String statusKey;

  /// O dia da primeira cobrança de uma assinatura que começa numa data (a
  /// meia-noite desse dia em São Paulo, com o fuso); nulo quando o checkout
  /// cobra na hora ou começa por um teste em dias. O cartão é guardado sem
  /// cobrança e a cobrança acontece nesse dia.
  final String? subscriptionStartAt;

  /// Endereço https para onde o comprador volta depois de pagar; vazio sem ele.
  final String successUrl;

  /// O endereço hospedado desta sessão: redirecione o comprador para cá, ou
  /// abra-o no modal, e ele paga na página da Peráta exatamente a sessão que
  /// esta resposta abriu, que aparece no status_key, no GET da sessão e nos
  /// webhooks com o mesmo checkout_id. Quem abre o endereço depois do pagamento
  /// vê a confirmação e nada é cobrado de novo. Na repetição de uma criação
  /// idempotente o segredo não existe mais e o endereço volta a ser o do link,
  /// que abre uma sessão nova a cada visita.
  final String url;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'amount_cents': amountCents,
    'cancel_url': cancelUrl,
    'client_reference_id': clientReferenceId,
    'client_secret': clientSecret,
    'client_secret_expires_at': clientSecretExpiresAt,
    'created_at': createdAt,
    'discount_id': discountId,
    'expires_at': expiresAt,
    'first_period_extra_days': firstPeriodExtraDays,
    'id': id,
    'items': items.map((item) => item.toJson()).toList(),
    'label': label,
    'metadata': metadata,
    'notify_customer_email': notifyCustomerEmail,
    'price_id': priceId,
    'product_id': productId,
    'quantity': quantity,
    'renewal_mode': renewalMode,
    'session_id': sessionId,
    'showcase_id': showcaseId,
    'status': status,
    'status_key': statusKey,
    'subscription_start_at': subscriptionStartAt,
    'success_url': successUrl,
    'url': url,
  };
}

