    'billing_address': ?billingAddress?.toJson(),
    'billing_name': ?billingName,
    'created_at': createdAt,
    'email': email,
    'external_id': externalId,
    'id': id,
    'name': name,
    'phone': ?phone,
    'showcase_id': showcaseId,
    'status': status,
    'tax_id': ?taxId,
    'tax_id_kind': ?taxIdKind,
  };
}

