    'metadata': metadata,
    'order_status': orderStatus,
    'paid_at': paidAt,
    'period_end': periodEnd,
    'period_start': periodStart,
    'price_id': priceId,
    'product_id': productId,
    'refunded_amount_cents': refundedAmountCents,
    'showcase_id': showcaseId,
