    'amount_cents': amountCents,
    'fee_cents': feeCents,
    'net_cents': netCents,
    'recipient_id': recipientId,
  };
}

/// Subscription is a resource of Peráta's API.
final class Subscription {
  const Subscription({
    required this.amountCents,
    required this.cancelAtPeriodEnd,
    required this.clientReferenceId,
    required this.currency,
    required this.currentPeriodEnd,
    required this.currentPeriodStart,
    required this.customerId,
    this.discountEndsAt,
    this.discountId,
    this.firstPeriodExtraDays,
    required this.id,
    required this.interval,
    required this.label,
    required this.metadata,
    required this.notifyCustomerEmail,
    this.pendingUpdate,
    required this.priceId,
    required this.productId,
    required this.quantity,
    required this.renewalMode,
    required this.showcaseId,
    required this.status,
    this.suspendedAt,
    this.suspensionReason,
    this.trialEnd,
    this.trialStart,
  });

  /// A Subscription out of the API's JSON.
  factory Subscription.fromJson(Map<String, Object?> json) {
    return Subscription(
      amountCents: json['amount_cents'] as int,
      cancelAtPeriodEnd: json['cancel_at_period_end'] as bool,
      clientReferenceId: json['client_reference_id'] as String,
      currency: json['currency'] as String,
      currentPeriodEnd: json['current_period_end'] as String,
      currentPeriodStart: json['current_period_start'] as String,
      customerId: json['customer_id'] as String,
      discountEndsAt: json['discount_ends_at'] as String?,
      discountId: json['discount_id'] as String?,
      firstPeriodExtraDays: json['first_period_extra_days'] as int?,
      id: json['id'] as String,
      interval: json['interval'] as String,
      label: json['label'] as String,
      metadata: readMap(json['metadata'], (value) => value),
      notifyCustomerEmail: json['notify_customer_email'] as bool,
      pendingUpdate: readOptional(
        json['pending_update'],
        (value) => SubscriptionPendingUpdate.fromJson(readObject(value)),
      ),
      priceId: json['price_id'] as String,
      productId: json['product_id'] as String,
      quantity: json['quantity'] as int,
      renewalMode: json['renewal_mode'] as String,
      showcaseId: json['showcase_id'] as String,
      status: json['status'] as String,
      suspendedAt: json['suspended_at'] as String?,
      suspensionReason: json['suspension_reason'] as String?,
      trialEnd: json['trial_end'] as String?,
      trialStart: json['trial_start'] as String?,
    );
  }

  /// O que a assinatura cobra a cada ciclo, em centavos, já para a quantity que
  /// ela tem: é o total do ciclo, não o preço de uma unidade. O preço por
  /// unidade, por assento ou por faixas já está aplicado à quantity.
  final int amountCents;

  final bool cancelAtPeriodEnd;

  /// O id do pedido no seu sistema, enviado ao criar o checkout que vendeu a
  /// assinatura; vazio sem ele. Cada pedido de renovação traz o mesmo
  /// client_reference_id, e o mesmo metadata, para você achar o cliente.
  final String clientReferenceId;

  /// One of `BRL`.
  final String currency;

  final String currentPeriodEnd;

  final String currentPeriodStart;

  final String customerId;

  /// Quando o desconto deixa de valer: o fim do último ciclo que ele ainda
  /// abate (num desconto de uma vez, o fim do primeiro ciclo pago; por alguns
  /// meses, o fim do último ciclo desses meses). Nulo quando não há desconto e
  /// quando ele vale para sempre.
  final String? discountEndsAt;

  /// O desconto em vigor na assinatura, que se aplica aos próximos ciclos até
  /// acabar; nulo sem desconto e depois que ele acabou.
  final String? discountId;

  /// Quantos dias o checkout que vendeu a assinatura somou ao primeiro período,
  /// para você conferir; nulo quando o primeiro período foi o comum. O primeiro
  /// período vai do dia do pagamento até esse dia mais um intervalo do preço
  /// mais estes dias, e current_period_end já vem com eles.
  final int? firstPeriodExtraDays;

  final String id;

  final String interval;

  /// O nome que você deu à assinatura, copiado do label do checkout que a
  /// vendeu (por exemplo, Olho de Águia · Colaborador Ana); vazio sem ele. É o
  /// título da assinatura no portal do cliente e no painel. Troque com PATCH,
  /// até 200 caracteres.
  final String label;

  /// Metadados do lojista: pares chave e valor (texto, número ou booleano);
  /// objeto vazio quando não há.
  final Map<String, Object?> metadata;

  /// Verdadeiro enquanto a Peráta escreve ao comprador a cada cobrança de
  /// renovação; falso quando o seu sistema avisa o comprador e a Peráta fica
  /// quieta. Vem do notify_customer_email do checkout (verdadeiro por padrão) e
  /// ainda depende do aviso Cobrança da renovação em Configurações ›
  /// Preferências, que a organização pode desligar.
  final bool notifyCustomerEmail;

  /// A mudança de plano ou de quantidade agendada para o próximo período (PATCH
  /// com proration_behavior next_period); nulo quando não há nenhuma. Até
  /// effective_at a assinatura segue com o price_id, a quantity e o
  /// amount_cents de cima.
  final SubscriptionPendingUpdate? pendingUpdate;

  final String priceId;

  final String productId;

  /// Quantas unidades ou assentos a assinatura cobre, de 1 em diante; 1 num
  /// preço sem quantidade. amount_cents é o total do ciclo para esta quantity.
  final int quantity;

  /// Como os próximos períodos são cobrados: manual (a cada ciclo a Peráta abre
  /// uma cobrança para o comprador pagar, com o evento
  /// subscription.renewal_due, e o cartão nunca é cobrado), card (o cartão de
  /// crédito guardado é cobrado sozinho) ou pix_automatic (o banco debita cada
  /// cobrança, autorizada uma vez pelo comprador). card e pix_automatic são os
  /// modos automáticos. Vem do renewal_mode do checkout; sem ele, é card quando
  /// o pagamento guardou o cartão e manual nos outros meios. Troque com PATCH
  /// (manual, ou card quando há cartão guardado).
  ///
  /// One of `manual`, `card`, `pix_automatic`.
  final String renewalMode;

  /// O showcase a que pertence: o da chave de API que fez a chamada. Uma chave
  /// só alcança o seu showcase.
  final String showcaseId;

  /// One of `trialing`, `active`, `past_due`, `suspended`, `paused`,
  /// `canceled`.
  final String status;

  /// Quando a assinatura foi suspensa; nulo enquanto não está suspensa.
  final String? suspendedAt;

  /// Por que foi suspensa: retries_exhausted (o cartão foi recusado em todas as
  /// tentativas), declined_not_retryable (o emissor recusou sem permitir nova
  /// tentativa) ou dispute (o comprador contestou o pagamento); nulo enquanto
  /// não está suspensa.
  ///
  /// One of `retries_exhausted`, `declined_not_retryable`, `dispute`.
  final String? suspensionReason;

  final String? trialEnd;

  final String? trialStart;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'amount_cents': amountCents,
    'cancel_at_period_end': cancelAtPeriodEnd,
    'client_reference_id': clientReferenceId,
    'currency': currency,
    'current_period_end': currentPeriodEnd,
    'current_period_start': currentPeriodStart,
    'customer_id': customerId,
    'discount_ends_at': discountEndsAt,
    'discount_id': discountId,
    'first_period_extra_days': firstPeriodExtraDays,
    'id': id,
    'interval': interval,
    'label': label,
    'metadata': metadata,
    'notify_customer_email': notifyCustomerEmail,
    'pending_update': pendingUpdate?.toJson(),
    'price_id': priceId,
    'product_id': productId,
    'quantity': quantity,
    'renewal_mode': renewalMode,
    'showcase_id': showcaseId,
    'status': status,
    'suspended_at': suspendedAt,
    'suspension_reason': suspensionReason,
    'trial_end': trialEnd,
    'trial_start': trialStart,
  };
}

/// UsageError is a resource of Peráta's API.
final class UsageError {
  const UsageError({
    required this.error,
    this.fields,
    this.message,
    this.record,
  });

  /// A UsageError out of the API's JSON.
  factory UsageError.fromJson(Map<String, Object?> json) {
    return UsageError(
      error: json['error'] as String,
      fields: readOptional(
        json['fields'],
        (value) => readMap(value, (value) => readList(value, readString)),
      ),
      message: json['message'] as String?,
      record: json['record'] as int?,
    );
  }

  /// Código do erro: invalid_credential, invalid_request, conflict,
  /// unsupported_media_type, body_too_large, rate_limited ou unavailable.
  final String error;

  /// Em invalid_request, o que há de errado em cada campo do evento.
  final Map<String, List<String>>? fields;

  /// O que explica a recusa, em português.
  final String? message;

  /// Posição, a partir de 1, do evento do lote que causou a recusa
  /// (invalid_request e conflict); o lote inteiro foi revertido.
  final int? record;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'error': error,
    'fields': ?fields,
    'message': ?message,
    'record': ?record,
  };
}

