  final String? checkoutLinkId;

  /// O id do pedido no sistema do lojista; vazio sem ele. Na renovação de uma
  /// assinatura é o do checkout que a vendeu.
  final String? clientReferenceId;

  final String createdAt;

  /// One of `BRL`.
  final String currency;

  /// Nulo até o comprador confirmar.
  final String? customerId;

  /// O ciclo da assinatura que o pagamento cobra: 1 é o primeiro, 2 é a
  /// primeira renovação.
  final int? cycleSequence;

